import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        List<Expense> expenses = new ArrayList<>();
        Scanner input = new Scanner(System.in);
        while (input.hasNextLine()) {
            String line = input.nextLine();
            if (line.equals("konec")) break;
            if (line.equals("seznam")) {
                for (Expense e : expenses) System.out.println(e.category() + ": " + e.cents() + " haléřů");
            } else if (line.equals("soucet")) {
                long sum = 0;
                for (Expense e : expenses) sum = Math.addExact(sum, e.cents());
                System.out.println(sum);
            } else if (line.startsWith("pridej ")) {
                String[] parts = line.substring(7).split(" ", 2);
                try {
                    if (parts.length != 2) throw new IllegalArgumentException("pridej HALEŘE KATEGORIE");
                    expenses.add(new Expense(parts[1], Long.parseLong(parts[0])));
                } catch (IllegalArgumentException e) { System.out.println("Chybný výdaj: " + e.getMessage()); }
            } else System.out.println("Příkazy: pridej HALEŘE KATEGORIE, seznam, soucet, konec");
        }
    }
}

