Vzorové jádro; chyby souboru se zde propagují jako IOException. Pro přívětivé CLI je zachyť až na hranici aplikace.

```java
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public class Main {
    public static void main(String[] args) throws IOException {
        Path file = Path.of("contacts.tsv");
        Map<String, Contact> contacts = new LinkedHashMap<>();
        if (Files.exists(file)) {
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                String[] parts = line.split("\t", -1);
                if (parts.length != 2 || parts[0].isBlank() || parts[1].isBlank()) throw new IOException("Neplatný řádek kontaktů");
                contacts.put(parts[0], new Contact(parts[0], parts[1]));
            }
        }
        Scanner input = new Scanner(System.in);
        while (input.hasNextLine()) {
            String line = input.nextLine();
            if (line.equals("konec")) break;
            if (line.equals("seznam")) {
                contacts.values().forEach(c -> System.out.println(c.name() + " <" + c.email() + ">"));
            } else if (line.startsWith("pridej ")) {
                String[] parts = line.substring(7).split(" ", 2);
                if (parts.length != 2 || parts[0].contains("\t") || parts[1].isBlank() || parts[1].contains("\t")) {
                    System.out.println("Použij pridej EMAIL JMÉNO; bez tabulátorů."); continue;
                }
                contacts.put(parts[1], new Contact(parts[1], parts[0]));
            } else if (line.startsWith("najdi ")) {
                System.out.println(contacts.getOrDefault(line.substring(6), new Contact("Nenalezeno", "–")));
            } else if (line.startsWith("smaz ")) contacts.remove(line.substring(5));
            else if (line.equals("uloz")) {
                List<String> rows = new ArrayList<>();
                for (Contact c : contacts.values()) rows.add(c.name() + "\t" + c.email());
                Files.write(file, rows, StandardCharsets.UTF_8);
                System.out.println("Uloženo");
            } else System.out.println("Příkazy: pridej EMAIL JMÉNO, najdi JMÉNO, smaz JMÉNO, seznam, uloz, konec");
        }
    }
}

```

