Referenční agregace. Pro produkčnější chybové zprávy doplň číslo řádku do parseru a hlídání přetečení podle zvolených limitů dat.

```java
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;
public class Main {
    public static void main(String[] args) throws java.io.IOException {
        List<Expense> rows = new ArrayList<>();
        for (String line : Files.readAllLines(Path.of("expenses.csv"), StandardCharsets.UTF_8)) {
            if (line.isBlank() || line.equals("category,cents")) continue;
            String[] parts = line.split(",", -1);
            if (parts.length != 2) throw new IllegalArgumentException("Očekávám category,cents");
            rows.add(new Expense(parts[0], Long.parseLong(parts[1])));
        }
        Map<String, Long> totals = rows.stream().collect(Collectors.groupingBy(
            Expense::category, TreeMap::new, Collectors.summingLong(Expense::cents)));
        totals.forEach((category, cents) -> System.out.println(category + ": " + cents));
        long largeCount = rows.stream().filter(e -> e.cents() >= 5000).count();
        System.out.println("Výdaje od 5000 haléřů: " + largeCount);
        long sum = rows.stream().mapToLong(Expense::cents).sum();
        System.out.println("Součet: " + sum);
        System.out.println("Počet: " + rows.size());
    }
}

